def test_render_keeps_status_on_one_line() -> None:
    """A multi-line status would spill markup into the header block."""
    out = fetch_url.render("https://x.test/p", "FAILED (404: <html>\n<body>)", "", "")
    header = out.split("\n\n")[0].splitlines()
    assert len(header) == 3
    assert header[2].startswith("# Status: FAILED (404: <html> <body>)")


def test_fetch_collapses_html_error_body_into_status() -> None:
    """Upstream error pages are full HTML documents with newlines."""
    body = "<!DOCTYPE html>\n<html>\n<body>Page not found</body>\n</html>"
