def test_upstream_403_is_recorded_not_fatal() -> None:
    """Bot-protection 403s are routine; they must not abort the run.

    Regression: an upstream Cloudflare block was misread as a proxy policy
    denial and exited 3, killing a batch mid-fetch.
    """
    body = "<html><head><title>403 Forbidden</title></head><body>Denied</body></html>"
    with patch.object(fetch_url.urllib.request, "urlopen", _raise_http(403, body)):
        status, _, _ = fetch_url.fetch("https://blocked.test/p")
    assert status.startswith("FAILED (403")


