def test_extracts_mediawiki_external_links_only() -> None:
    """MediaWiki marks citations with class=external; internal links are noise."""
    html = """
    <a href="/wiki/Internal">internal</a>
    <a href="https://en.wikipedia.org/wiki/Other">same host</a>
    <a class="external text" href="https://www.irs.gov/pub/p527">ref 1</a>
    <a class="external autonumber" href="https://eur-lex.europa.eu/x">ref 2</a>
    <a href="https://example.com/unmarked">unmarked</a>
    """
    refs = fetch_url.extract_reference_urls(html, "https://en.wikipedia.org/wiki/X")
    assert refs == ["https://www.irs.gov/pub/p527", "https://eur-lex.europa.eu/x"]


